using System.Net;
using System.Text;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>Local HTTP server standing in for the provider; records what it receives and replies with a canned answer.</summary>
public sealed class FakeProviderServer : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly int status;
    private readonly string body;

    public FakeProviderServer(int status, string body)
    {
        this.status = status;
        this.body = body;
        var port = GetFreePort();
        BaseAddress = new Uri($"http://localhost:{port}/");
        listener.Prefixes.Add(BaseAddress.ToString());
        listener.Start();
        _ = Task.Run(Serve);
    }

    public Uri BaseAddress { get; }
    public string? Method { get; private set; }
    public string? Path { get; private set; }
    public string? ContentType { get; private set; }
    public string? RequestBody { get; private set; }

    private async Task Serve()
    {
        try
        {
            while (listener.IsListening)
            {
                var ctx = await listener.GetContextAsync();
                Method = ctx.Request.HttpMethod;
                Path = ctx.Request.Url!.AbsolutePath;
                ContentType = ctx.Request.ContentType;
                using (var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8))
                    RequestBody = await reader.ReadToEndAsync();

                var bytes = Encoding.UTF8.GetBytes(body);
                ctx.Response.StatusCode = status;
                ctx.Response.ContentType = "application/json";
                await ctx.Response.OutputStream.WriteAsync(bytes);
                ctx.Response.Close();
            }
        }
        catch (Exception e) when (e is HttpListenerException or ObjectDisposedException or InvalidOperationException)
        {
        }
    }

    private static int GetFreePort()
    {
        var l = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        l.Start();
        var port = ((IPEndPoint)l.LocalEndpoint).Port;
        l.Stop();
        return port;
    }

    public void Dispose() => listener.Close();
}
