using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static async Task<(AuthorizationOutcome Outcome, FakeProviderServer Server)> Authorize(int status, string body)
    {
        var server = new FakeProviderServer(status, body);
        using var client = new HttpClient { BaseAddress = server.BaseAddress };
        var outcome = await new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);
        return (outcome, server);
    }

    [Fact]
    public async Task The_authorization_is_posted_to_the_provider_with_the_agreed_json_shape()
    {
        var (_, server) = await Authorize(200, """{"status":"approved"}""");
        using var _s = server;

        Assert.Equal("POST", server.Method);
        Assert.Equal("/v1/authorizations", server.Path);
        Assert.StartsWith("application/json", server.ContentType);
        using var doc = JsonDocument.Parse(server.RequestBody!);
        var root = doc.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var (outcome, server) = await Authorize(200, """{"status":"approved"}""");
        server.Dispose();
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var (outcome, server) = await Authorize(200, """{"status":"declined"}""");
        server.Dispose();
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_refusal_with_payment_required_is_read_as_declined()
    {
        var (outcome, server) = await Authorize(402, """{"error":"insufficient_funds"}""");
        server.Dispose();
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unknown_status_is_never_treated_as_approved()
    {
        var (outcome, server) = await Authorize(200, """{"status":"pending"}""");
        server.Dispose();
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_treated_as_approved()
    {
        var (outcome, server) = await Authorize(200, """{"decision":"approved"}""");
        server.Dispose();
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_instead_of_a_decision(int status)
    {
        using var server = new FakeProviderServer(status, """{"error":"x"}""");
        using var client = new HttpClient { BaseAddress = server.BaseAddress };

        await Assert.ThrowsAsync<HttpRequestException>(() =>
            new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(1, "EUR"), CancellationToken.None));
    }
}
